var unitofwork = new unitofwork(context);
var beers = unitOfWork.Beers;
var beer = new Beer {
Name = ''Fuller", Style = "Porter"
}
beers.Add(beer);
var brands = unitOfWork.Brand;
var brand = new Brand{
Name = "fuller;s brewery "
brands.Add(brand);
unitOfWork.Save();
}

private DesingPatternsContext _ context;
public IRepository<Beer> _beers ;
public IRepository <Brand> _brand;

public IRespository<Beer> Beers {
get{
return _beers == null?
_beers = new Repository<Beer> (_context):
_beers
}
}
public IRespository<Brand> Brand{
get{
return _brand == null?
_brand = new Repository<Brand> (_context):
_brand
}
}
public UnitOfWork(DesingPatternsContext context){
_context = context
}
public void Save() {
_context.SaveChanges()
}
